<template>
  <div class="campus">
    <header><div class="brand">校园午餐<span>提前预订 · 按时自提</span></div><a href="/#/meal">商家管理</a></header>
    <div class="notice">当前为本地演示：支付和退款使用模拟流程。餐次时间均为北京时间。</div>
    <section v-if="!token" class="login-panel"><h1>把午餐安排好，再去上课。</h1><p>登录后选择餐次与菜品，取餐时向工作人员出示核销码。</p><el-input v-model="loginCode" placeholder="演示账号 local-demo / local-second" /><el-button type="primary" @click="login">登录演示账号</el-button></section>
    <template v-else>
      <div class="welcome"><h1>今天的午餐，提前安排。</h1><el-button size="small" @click="refresh">刷新</el-button><el-button size="small" @click="logout">退出</el-button></div>
      <section class="sessions"><div v-for="session in sessions" :key="session.id" :class="['session', {active:sessionId===session.id}]" @click="selectSession(session)"><div class="date">{{ session.mealDate }}</div><h3>{{ session.title }}</h3><p>截单 {{ session.cutoffTime }}</p><p>自提 {{ session.pickupStart }} ～ {{ session.pickupEnd }}</p><strong>剩余 {{ session.capacity - session.reservedCount }} / {{ session.capacity }} 份</strong></div><p v-if="!sessions.length">暂无开放预订的餐次，可联系商家发布餐次。</p></section>
      <div class="content"><section class="catalog"><h2>选择午餐</h2><el-select v-model="categoryId" placeholder="菜品分类" @change="loadDishes"><el-option v-for="category in categories" :key="category.id" :label="category.name" :value="category.id" /></el-select><div v-for="dish in dishes" :key="dish.id" class="dish"><div><h3>{{ dish.name }}</h3><p>{{ dish.description || '现做午餐，按餐次集中备餐。' }}</p><strong>¥ {{ Number(dish.price).toFixed(2) }}</strong></div><el-button size="small" type="primary" @click="add(dish)">加入预订</el-button></div></section>
        <aside class="checkout"><h2>我的预订</h2><div v-for="item in cart" :key="item.id" class="cart-item"><span>{{ item.name }} × {{ item.number }}</span><el-button type="text" @click="sub(item)">减一份</el-button></div><p v-if="!cart.length">还没有选择午餐</p><div v-if="quote" class="price"><p>餐盒费 <span>¥ {{ quote.packAmount }}</span></p><p>配送费 <span>¥ {{ quote.deliveryFee }}</span></p><p class="total">合计 <strong>¥ {{ quote.amount }}</strong></p><small>以服务器确认的菜品价格与费用为准。</small></div><el-input v-model="contactName" placeholder="取餐人" maxlength="50" /><el-input v-model="contactPhone" placeholder="11位手机号" maxlength="11" /><el-input v-model="remark" placeholder="备注（选填）" maxlength="100" /><el-button type="primary" class="submit" :disabled="!sessionId || !cart.length || !!createdOrder" :loading="busy" @click="submit">确认预订</el-button><el-button v-if="pendingRequest" type="text" @click="submit">恢复/重试上次预订</el-button><el-button v-if="pendingRequest" type="text" @click="newOrder">开始下一笔预订</el-button><p v-if="createdOrder" class="created">预订成功，金额 ¥ {{ createdOrder.orderAmount }}。请在下方订单中完成模拟支付。</p></aside>
      </div>
      <section class="history"><h2>我的午餐订单</h2><article v-for="order in orders" :key="order.id" class="order"><div><span class="badge">{{ state(order) }}</span><h3>{{ order.address }}</h3><p>{{ order.orderDishes }}</p><p>预订时间 {{ order.orderTime }} · 金额 ¥ {{ order.amount }}</p><p class="code" v-if="order.pickupCode && order.status !== 6">取餐码 <strong>{{ order.pickupCode }}</strong></p><small v-if="order.status === 4">请在该餐次自提时段内向工作人员出示取餐码。</small></div><div class="order-actions"><el-button v-if="order.status === 1" type="primary" size="small" @click="pay(order)">模拟支付</el-button><el-button v-if="order.status === 1 || order.status === 2" size="small" @click="cancel(order)">取消预订</el-button><el-button size="small" @click="detail(order)">查看明细</el-button></div></article><p v-if="!orders.length">还没有预订记录</p></section>
    </template>
  </div>
</template>
<script lang="ts">
import Vue from 'vue'
function newKey(): string { return Array.from(window.crypto.getRandomValues(new Uint8Array(16))).map(value => value.toString(16).padStart(2,'0')).join('') }
export default Vue.extend({
  data() { return { token: localStorage.getItem('campus-token') || '', userId: localStorage.getItem('campus-user') || '', loginCode: 'local-demo', sessions: [] as any[], sessionId: '', categories: [] as any[], categoryId: '', dishes: [] as any[], cart: [] as any[], quote: null as any, orders: [] as any[], contactName: '同学', contactPhone: '13800000000', remark: '', pendingRequest: null as any, createdOrder: null as any, busy: false, timer: 0 } },
  mounted() { if (this.token) { this.restoreDraft(); this.refresh() }; this.timer = window.setInterval(() => { if (this.token) { this.loadHistory() } }, 10000) },
  beforeDestroy() { window.clearInterval(this.timer) },
  methods: {
    async api(method: string, url: string, payload?: any): Promise<any> {
      const response = await fetch(url, { method, headers: { 'Content-Type':'application/json', 'authentication':this.token }, body: payload === undefined ? undefined : JSON.stringify(payload) })
      if (response.status === 401) { this.logout(); throw new Error('登录已过期，请重新登录') }
      const result = await response.json(); if (result.code !== 1) { throw new Error(result.msg || '操作失败') }; return result.data
    },
    async action(work: () => Promise<any>) { try { await work() } catch (error) { this.$message.error(error.message || '操作失败') } },
    async login() { await this.action(async () => { const user = await this.api('POST','/user/user/login',{code:this.loginCode}); this.token = user.token; this.userId = String(user.id); localStorage.setItem('campus-token',this.token); localStorage.setItem('campus-user',this.userId); this.restoreDraft(); await this.refresh() }) },
    logout() { this.token = ''; this.pendingRequest = null; this.createdOrder = null; localStorage.removeItem('campus-token'); localStorage.removeItem('campus-user') },
    restoreDraft() { const value = localStorage.getItem('campus-draft-'+this.userId); try { this.pendingRequest = value ? JSON.parse(value) : null } catch (_) { this.pendingRequest = null } },
    async refresh() { await this.action(async () => { this.sessions = await this.api('GET','/user/meal/sessions'); this.categories = await this.api('GET','/user/category/list?type=1'); if (!this.categoryId && this.categories.length) { this.categoryId = this.categories[0].id }; await this.loadDishes(); await this.loadCart(); await this.loadHistory() }) },
    async selectSession(session: any) { this.sessionId = session.id; await this.loadCart() },
    async loadDishes() { if (this.categoryId) { this.dishes = await this.api('GET','/user/dish/list?categoryId='+this.categoryId) } },
    async loadCart() { this.cart = await this.api('GET','/user/shoppingCart/list'); this.quote = this.cart.length ? await this.api('GET','/user/order/quote?mealSessionId='+(this.sessionId || '1')) : null },
    async loadHistory() { await this.action(async () => { const history = await this.api('GET','/user/order/historyOrders?pageNum=1&pageSize=20'); this.orders = history.records.filter((order: any) => order.fulfillmentType === 2) }) },
    async add(dish: any) { await this.action(async () => { await this.api('POST','/user/shoppingCart/add',{dishId:dish.id}); await this.loadCart() }) },
    async sub(item: any) { await this.action(async () => { await this.api('POST','/user/shoppingCart/sub',{dishId:item.dishId,setmealId:item.setmealId,dishFlavor:item.dishFlavor}); await this.loadCart() }) },
    async submit() { this.busy = true; await this.action(async () => {
      if (!this.pendingRequest) { if (!this.sessionId) { throw new Error('请先选择餐次') }; if (!this.contactName.trim() || this.contactName.length > 32 || !/^[0-9]{11}$/.test(this.contactPhone)) { throw new Error('请填写32字以内的取餐人和11位手机号') }; this.pendingRequest = { requestKey:newKey(), mealSessionId:this.sessionId, contactName:this.contactName, contactPhone:this.contactPhone, remark:this.remark, payMethod:1, deliveryStatus:0, tablewareStatus:1 }; localStorage.setItem('campus-draft-'+this.userId,JSON.stringify(this.pendingRequest)) }
      this.createdOrder = await this.api('POST','/user/order/submit',this.pendingRequest); this.$message.success('预订已确认，请完成模拟支付'); await this.loadCart(); await this.loadHistory()
    }); this.busy = false },
    newOrder() { this.pendingRequest = null; this.createdOrder = null; localStorage.removeItem('campus-draft-'+this.userId) },
    async pay(order: any) { await this.action(async () => { await this.api('POST','/user/local/orders/'+order.number+'/pay'); this.$message.success('模拟支付成功'); await this.loadHistory(); this.sessions = await this.api('GET','/user/meal/sessions') }) },
    async cancel(order: any) { await this.action(async () => { await this.api('PUT','/user/order/cancel/'+order.id); this.$message.success('预订已取消，已支付订单进入退款流程'); await this.refresh() }) },
    async detail(order: any) { await this.action(async () => { const detail = await this.api('GET','/user/order/orderDetail/'+order.id); await this.$alert(detail.orderDetailList.map((item: any) => item.name+' × '+item.number+'，单价 ¥ '+item.amount).join('；'),'订单价格快照') }) },
    state(order: any) { const names: {[key: number]: string} = {1:'待支付',2:'待接单',3:'备餐中',4:'待自提',5:'已取餐',6:'已取消'}; const refund: {[key: string]: string} = {PENDING:'退款处理中',SUCCEEDED:'已退款',FAILED:'退款待商家处理'}; return names[order.status]+(refund[order.refundStatus]?' · '+refund[order.refundStatus]:'') }
  }
})
</script>
<style scoped>
.campus{max-width:1180px;margin:0 auto;padding:28px;color:#183340;background:#f6f8f5;min-height:100vh}.campus header,.welcome{display:flex;justify-content:space-between;align-items:center;gap:16px}.brand{font-size:25px;font-weight:700}.brand span{display:block;font-size:13px;font-weight:400;margin-top:6px;color:#667b73}a{color:#2e6656}.notice{background:#e7efe7;padding:12px 18px;border-radius:10px;color:#566b60;margin:22px 0;font-size:13px}.login-panel{max-width:540px;margin:70px auto;background:white;padding:38px;border-radius:18px}.login-panel .el-input{margin:20px 0}.welcome h1{flex:1;font-size:27px}.sessions{display:flex;gap:15px;flex-wrap:wrap;margin:18px 0 28px}.session{padding:20px;background:white;border:2px solid #e4eae4;border-radius:14px;cursor:pointer;min-width:280px;flex:1}.session.active{border-color:#2e6656;background:#eef6ed}.session h3{margin:10px 0}.session p{font-size:12px;color:#607169}.date{font-size:12px;letter-spacing:1px}.content{display:grid;grid-template-columns:1.5fr 1fr;gap:24px}.catalog,.checkout,.history{background:white;border-radius:15px;padding:25px}.dish{display:flex;align-items:center;justify-content:space-between;padding:22px 0;border-bottom:1px solid #eee;gap:18px}.dish h3{margin:0 0 7px}.dish p{font-size:13px;color:#7b857e}.dish strong{color:#2e6656}.checkout .el-input{margin-top:10px}.cart-item{display:flex;justify-content:space-between;align-items:center}.price{border-top:1px solid #ddd;margin-top:15px;padding-top:10px}.price p{display:flex;justify-content:space-between}.total{font-size:20px}.price small{color:#829085}.submit{width:100%;margin-top:18px}.created{background:#edf7ed;padding:12px;font-size:13px}.history{margin-top:26px}.order{border-top:1px solid #eee;padding:22px 0;display:flex;justify-content:space-between;gap:20px}.order p{font-size:13px;color:#66776b}.badge{background:#e7f0e7;padding:5px 9px;border-radius:6px;font-size:12px}.code strong{letter-spacing:1px;color:#2e6656}.order-actions{min-width:135px;display:flex;flex-direction:column;gap:8px}.order-actions .el-button{margin-left:0}@media(max-width:760px){.campus{padding:16px}.content{grid-template-columns:1fr}.order{flex-direction:column}.welcome h1{font-size:21px}}
</style>
